// build/x86asm/tokhash.hpp -- the keyword table of the scanner (asm/tokhash.c, generated by tokhash.pl from insns.dat,
// regs.dat and tokens.dat).
//
// A word the scanner reads is looked up here, whatever its case: an instruction name, a register, a prefix, a size or
// special-operand keyword, SEG/WRT/TIMES, the `__?float32?__` / `__?utf16?__` / `__?ilog2e?__` functions, the
// `__?infinity?__` constants, the AVX-512 decorators ({rn-sae}, {1to8}, {z}) and the AVX10 `dfv=` flags. Everything else
// is an identifier.
#pragma once

#include <string_view>

#include "build/x86asm/types.hpp"

namespace cb::build::x86asm {

// Look `token` up (nasm_token_hash). On a keyword sets tv.type, tv.integer (the register, opcode, prefix, size or
// function number), tv.inttwo (the prefix slot, byte size, or flags of a brace constant) and tv.flag (TokenFlags) and
// returns the type. Otherwise sets them to ID, 0, 0, 0 and returns ID. It does not touch tv.text or tv.start.
int token_hash(std::string_view token, TokenVal& tv);

// The length of the longest keyword (MAX_KEYWORD); a longer word is never one.
inline constexpr std::size_t MAX_KEYWORD = 17;

}  // namespace cb::build::x86asm
